def naive_relu(x):
    assert len(x.shape) == 2
    x = x.copy()
    for i in range(x.shape[0]):
        for j in range(x.shape[1]):
            x[i, j] = max(x[i, j], 0)
    return x

class NaiveDense:
    def __init__(self, input_size, output_size, activation=None):
        self.activation = activation
        self.W = keras.Variable(
            shape=(input_size, output_size), initializer="uniform"
        )
        self.b = keras.Variable(shape=(output_size,), initializer="zeros")

    def __call__(self, inputs):
        x = ops.matmul(inputs, self.W) + self.b
        if self.activation is not None:
            x = self.activation(x)
        return x

    @property
    def weights(self):
        return [self.W, self.b]

class NaiveSequential:
    def __init__(self, layers):
        self.layers = layers

    def __call__(self, inputs):
        x = inputs
        for layer in self.layers:
            x = layer(x)
        return x

    @property
    def weights(self):
        weights = []
        for layer in self.layers:
            weights += layer.weights
        return weights

class Batches:
    def __init__(self, images, labels, size=4):
        if len(images) != len(labels) or size <= 0:
            raise ValueError("Check lengths and positive batch size")
        self.images, self.labels = images, labels
        self.size, self.index = size, 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.index >= len(self.images):
            raise StopIteration
        start = self.index
        self.index += self.size
        return (self.images[start:self.index],
                self.labels[start:self.index])

