def row_sums(x):
    if x.ndim != 2:
        raise ValueError("Expected a matrix")
    totals = np.zeros(x.shape[0], dtype="float64")
    for i in range(x.shape[0]):
        for j in range(x.shape[1]):
            totals[i] += x[i, j]
    return totals

